from sqlalchemy.orm import Session, joinedload
from sqlalchemy import func
from . import models, schemas

# Project CRUD
def get_project(db: Session, project_id: int):
    return db.query(models.Project).filter(models.Project.id == project_id).first()

def get_projects(db: Session, skip: int = 0, limit: int = 100):
    return db.query(models.Project).offset(skip).limit(limit).all()

def create_project(db: Session, project: schemas.ProjectCreate):
    db_project = models.Project(**project.model_dump())
    db.add(db_project)
    db.commit()
    db.refresh(db_project)
    return db_project

# Task CRUD
def get_tasks(db: Session, project_id: int, skip: int = 0, limit: int = 100):
    return (
        db.query(models.Task)
        .options(joinedload(models.Task.predecessors))
        .filter(models.Task.project_id == project_id)
        .offset(skip)
        .limit(limit)
        .all()
    )

def create_task(db: Session, task: schemas.TaskCreate, project_id: int):
    payload = task.model_dump(exclude={"predecessors"})
    db_task = models.Task(**payload, project_id=project_id)

    for predecessor_id in task.predecessors:
        predecessor = db.query(models.Task).filter(models.Task.id == predecessor_id).first()
        if predecessor:
            db_task.predecessors.append(predecessor)

    db.add(db_task)
    db.commit()
    db.refresh(db_task)
    return db_task

def update_task(db: Session, task_id: int, task_in: schemas.TaskUpdate):
    db_task = db.query(models.Task).filter(models.Task.id == task_id).first()
    if db_task:
        # Exclude 'predecessors' from the direct model_dump as it's handled separately
        data_to_update = task_in.model_dump(exclude_unset=True, exclude={"predecessors"})

        for var, value in data_to_update.items():
            setattr(db_task, var, value)

        if task_in.predecessors is not None:
            # Clear existing predecessors
            db_task.predecessors.clear()
            # Add new predecessors
            new_predecessors = db.query(models.Task).filter(
                models.Task.id.in_(task_in.predecessors),
                models.Task.project_id == db_task.project_id
            ).all()
            for predecessor in new_predecessors:
                db_task.predecessors.append(predecessor)

        db.add(db_task)
        db.commit()
        db.refresh(db_task)
    return db_task

def delete_task(db: Session, task_id: int):
    db_task = db.query(models.Task).filter(models.Task.id == task_id).first()
    if db_task:
        db.delete(db_task)
        db.commit()
    return db_task

# Risk CRUD
def get_risk(db: Session, risk_id: int):
