  const setDraftValue = (taskId: number, field: keyof Task, value: any) => {
    setDrafts((prev) => ({
      ...prev,
      [taskId]: { ...(prev[taskId] || {}), [field]: value },
    }));
  };

  const commitDraftValue = async (taskId: number, field: keyof Task) => {
