      <Paper elevation={3} sx={{ borderRadius: 3, overflow: 'hidden', flex: 1, minHeight: 0 }}>
        <Box sx={{ maxHeight: '60vh', overflow: 'auto', minWidth: 0 }}>
          <TableContainer>
            <Table 
              size="small" 
