                  letterSpacing: 0.2,
                } 
              }}
            >
              <TableHead>
                <TableRow>
                  <TableCell sx={{ width: 50 }}>ID</TableCell>
                  <TableCell sx={{ minWidth: 220 }}>Task</TableCell>
                  <TableCell align="center" sx={{ width: 110 }}>Duration (days)</TableCell>
