                  <TableCell sx={{ width: 170 }}>Start Date</TableCell>
                  <TableCell sx={{ minWidth: 220 }}>Predecessors</TableCell>
                  <TableCell sx={{ width: 120 }} />
                </TableRow>
              </TableHead>
              <TableBody>
