                      <Box sx={{ mt: 0.5, display: 'flex', flexWrap: 'wrap', gap: 0.5 }}>
                        {task.dependencies.map((pId) => ( // Use task.dependencies
                          <Chip key={pId} label={taskMap.get(pId)?.text || String(pId)} size="small" />
