                        InputLabelProps={{ shrink: true }}
                        InputProps={{ sx: { fontSize: 14, py: 1 } }}
                        onChange={(e) => setDraftValue(task.id, 'start_date', e.target.value)}
                        onBlur={() => commitDraftValue(task.id, 'start_date')}
                        disabled={isLoading_}
                      />
